<script setup lang="ts">import{reactive}from'vue';import{BarChart3,Download,Filter,Hotel,Printer,X}from'@lucide/vue';import Column from'primevue/column';import DataTable from'../../../Components/Ui/DataTable.vue';import FormInput from'../../../Components/Ui/FormInput.vue';import InputPencarian from'../../../Components/Ui/InputPencarian.vue';import{useKunjunganRanap}from'./useKunjunganRanap';const props=defineProps({token:{type:String,required:true}});const x=reactive(useKunjunganRanap(props))</script>
<template><section class="visit-report-module"><header class="visit-report-header"><div><span>Laporan Pelayanan</span><h1>Kunjungan Rawat Inap</h1><p>Adaptasi laporan DlgKunjunganRanap SIMRS Khanza.</p></div><Hotel :size="30"/></header><nav class="visit-report-tabs"><button v-for="t in [{v:'masuk',l:'Pasien Masuk'},{v:'pulang',l:'Pasien Pulang'},{v:'berulang',l:'Kunjungan Berulang'}]" :key="t.v" :class="{active:x.filter.jenis===t.v}" @click="x.gantiJenis(t.v)">{{t.l}}</button></nav>
<form class="visit-report-filter" @submit.prevent="x.muat"><FormInput v-model="x.filter.tanggal_mulai" label="Tanggal Mulai" type="date"/><FormInput v-model="x.filter.tanggal_selesai" label="Sampai Dengan" type="date"/><template v-if="!x.berulang"><FormInput v-model="x.filter.status" label="Status Kunjungan" jenis="select" :options="[{label:'Semua',value:''},{label:'Baru',value:'Baru'},{label:'Lama',value:'Lama'}]"/><InputPencarian v-model="x.pilihan.bangsal" label="Bangsal/Ruang" :search="q=>x.refData('bangsal',q)"/><InputPencarian v-model="x.pilihan.dokter" label="Dokter/DPJP" :search="q=>x.refData('dokter',q)"/><InputPencarian v-model="x.pilihan.penjamin" label="Cara Bayar" :search="q=>x.refData('penjamin',q)"/><InputPencarian v-model="x.pilihan.kabupaten" label="Kabupaten" :search="q=>x.refData('kabupaten',q)"/><InputPencarian v-model="x.pilihan.kecamatan" label="Kecamatan" :search="q=>x.refData('kecamatan',q)"/><InputPencarian v-model="x.pilihan.kelurahan" label="Kelurahan" :search="q=>x.refData('kelurahan',q)"/></template><FormInput v-model="x.filter.q" class="visit-search" label="Pencarian" placeholder="No. rawat, RM, pasien, kamar, diagnosis..."/><button><Filter :size="16"/> Tampilkan</button></form>
<div class="visit-report-summary"><article><span>Total Data</span><strong>{{x.ringkasan.total}}</strong></article><template v-if="!x.berulang"><article><span>Pasien Lama</span><strong>{{x.ringkasan.lama}}</strong></article><article><span>Pasien Baru</span><strong>{{x.ringkasan.baru}}</strong></article></template><template v-else><article><span>Berulang</span><strong>{{x.ringkasan.berulang}}</strong></article><article><span>Tidak Berulang</span><strong>{{x.ringkasan.tidak_berulang}}</strong></article></template><article><span>Laki-laki</span><strong>{{x.ringkasan.laki_laki}}</strong></article><article><span>Perempuan</span><strong>{{x.ringkasan.perempuan}}</strong></article></div>
<div class="visit-report-tools"><span>{{x.data.length}} baris</span><button class="chart-button" @click="x.grafikVisible=!x.grafikVisible"><X v-if="x.grafikVisible" :size="15"/><BarChart3 v-else :size="15"/> Grafik</button><button @click="x.excel"><Download :size="15"/> Excel</button><button @click="x.cetak"><Printer :size="15"/> Cetak</button></div>
<section v-if="x.grafikVisible" class="visit-analytics"><header><div><span>Visualisasi</span><h2>Grafik Rawat Inap</h2><p>Ringkasan visual mengikuti data dan filter yang sedang ditampilkan.</p></div><BarChart3/></header><div class="visit-chart-grid">
<article v-if="!x.berulang" class="visit-chart-card trend-chart"><h3>Tren {{x.filter.jenis==='pulang'?'Pasien Pulang':'Pasien Masuk'}} per Hari</h3><p>Jumlah pasien berdasarkan tanggal pada periode laporan.</p><div v-if="x.tren.length" class="vertical-chart"><div v-for="i in x.tren" :key="i.label"><span><i :style="{height:`${Math.max(i.persen,3)}%`}"></i><b>{{i.nilai}}</b></span><small>{{i.label.slice(5)}}</small></div></div><em v-else>Belum ada data untuk divisualisasikan.</em></article>
<article v-for="g in [{judul:x.berulang?'Status Kunjungan':'Berdasarkan Ruang',data:x.ruang},{judul:'Berdasarkan Penyakit',data:x.penyakit}]" :key="g.judul" class="visit-chart-card rank-chart"><h3>{{g.judul}}</h3><p>Menampilkan seluruh kategori yang ditemukan.</p><div v-if="g.data.length" class="horizontal-chart"><div v-for="i in g.data" :key="i.label"><label><span :title="i.label">{{i.label}}</span><b>{{i.nilai}}</b></label><i><u :style="{width:`${i.persen}%`}"></u></i></div></div><em v-else>Belum ada data untuk divisualisasikan.</em></article>
<article v-if="!x.berulang" class="visit-chart-card rank-chart"><h3>Berdasarkan DPJP</h3><p>Jumlah pasien yang ditangani setiap dokter.</p><div v-if="x.dokter.length" class="horizontal-chart"><div v-for="i in x.dokter" :key="i.label"><label><span :title="i.label">{{i.label}}</span><b>{{i.nilai}}</b></label><i><u :style="{width:`${i.persen}%`}"></u></i></div></div><em v-else>Belum ada data untuk divisualisasikan.</em></article>
<article class="visit-chart-card donut-card"><h3>Jenis Kelamin</h3><p>Komposisi pasien pada hasil laporan.</p><div class="donut-content"><i class="donut gender" :style="{'--value':`${x.persenGender}%`}"><b>{{x.persenGender}}%</b><small>Laki-laki</small></i><ul><li><i></i>Laki-laki <b>{{x.ringkasan.laki_laki}}</b></li><li><i></i>Perempuan <b>{{x.ringkasan.perempuan}}</b></li></ul></div></article>
<article v-if="!x.berulang" class="visit-chart-card donut-card"><h3>Status Kunjungan</h3><p>Perbandingan pasien baru dan lama.</p><div class="donut-content"><i class="donut status" :style="{'--value':`${x.persenBaru}%`}"><b>{{x.persenBaru}}%</b><small>Pasien baru</small></i><ul><li><i></i>Baru <b>{{x.ringkasan.baru}}</b></li><li><i></i>Lama <b>{{x.ringkasan.lama}}</b></li></ul></div></article>
</div></section>
<div v-if="x.error" class="patient-error">{{x.error}}</div><DataTable v-else class="visit-report-table" :rows="x.data" :data-key="x.berulang?'no_rm':'no_rawat'" :loading="x.loading" paginator :rows-per-page="25" :rows-per-page-options="[25,50,100]" @page="x.gantiHalaman"><Column header="No."><template #body="{index}"><strong>{{x.firstRow+index+1}}</strong></template></Column><template v-if="!x.berulang"><Column header="RM / Pasien" style="min-width:210px"><template #body="{data:r}"><strong>{{r.nama_pasien}}</strong><small>{{r.no_rm}} · {{r.status_daftar}}</small></template></Column><Column header="Laki-laki"><template #body="{data:r}">{{r.jenis_kelamin==='L'?r.umur:'-'}}</template></Column><Column header="Perempuan"><template #body="{data:r}">{{r.jenis_kelamin==='P'?r.umur:'-'}}</template></Column><Column field="alamat" header="Alamat" style="min-width:280px"/><Column header="Diagnosis" style="min-width:300px"><template #body="{data:r}"><strong>{{r.kode_diagnosa}}</strong><small>{{r.diagnosa}}</small></template></Column><Column field="ruang" header="Ruang"/><Column field="status_pulang" header="Status Pulang"/><Column :field="x.filter.jenis==='pulang'?'tanggal_keluar':'tanggal_masuk'" :header="x.filter.jenis==='pulang'?'Tanggal Pulang':'Tanggal Masuk'"/><Column field="dpjp" header="DPJP" style="min-width:230px"/><Column field="lama_rawat" header="Lama Rawat"/><Column field="kelas" header="Kelas"/><Column field="no_sep" header="No. SEP"/></template><template v-else><Column field="no_rm" header="No. RM"/><Column field="nama_pasien" header="Nama Pasien"/><Column field="tanggal_lahir" header="Tgl. Lahir"/><Column field="alamat" header="Alamat"/><Column field="kode_diagnosa" header="Diagnosis"/><Column field="status_kunjungan" header="Status"/><Column field="jumlah_kunjungan" header="Jumlah"/></template></DataTable></section></template>
<style src="../KunjunganRalan/kunjungan-ralan.css" scoped></style>
